    openLoot(wave){this.loot.context=this;if(!this.ui.lootScreen||!this.ui.lootScreen.hidden)return false;const offers=this.loot.createOffers(wave,this.profession.selected,this.factions.selected),self=this;if(!offers.length)return false;this.lootWasPaused=Boolean(this.paused);this.paused=true;this.ui.lootKicker.textContent=wave%5===0?'BOSS TROPHY':'FIELD ARMORY CACHE';this.ui.lootIntro.textContent=wave%5===0?'擊破戰將後選擇一件戰利品，立即改變本局軍團。':'軍械波次守成：選擇裝備收入軍械庫，再配置給英雄或守軍。';this.ui.lootOptions.innerHTML='';offers.forEach(function(item){const button=document.createElement('button');button.type='button';button.dataset.lootId=item.id;if(item.gear){const compatible=this.armory.get(item.gear);item.description+=' 適用：'+(compatible.types||[]).map(id=>ns.config.units[id]?.name||id).join('、');}button.innerHTML='<span>'+item.icon+'</span><small>'+item.rarity+'</small><b>'+item.name+'</b><em>'+item.description+'</em>';if(item.gear){const gear=self.armory.get(item.gear),icon=button.querySelector('span');button.classList.add('gear-loot');icon.textContent='';icon.style.setProperty('--gear-column',gear.column);icon.style.setProperty('--gear-row',gear.row);}button.onclick=function(){self.claimLoot(item.id);};self.ui.lootOptions.appendChild(button);});this.ui.lootScreen.hidden=false;this.ui.lootOptions.querySelector('button').focus();return true;}
