    if(this.evolutionCamp||this.hero.evolution?.trialStage){if(this.evolutionCamp&&this.waveHUD)this.waveHUD.root.dataset.phase='preparing';this.ui.wave.textContent=this.hero.evolution?.trialStage?'試煉進行中':'完成遠征';this.ui.wave.disabled=this.status!=='playing'||this.paused||Boolean(this.hero.evolution?.trialStage);}
