    buttons.forEach((button,index)=>{if(!button)return;const label=skills[index],hint=hints[index],remaining=index===0?this.hero.novaCooldown:this.hero.skillCooldowns[['thunder','summon','ultimate'][index-1]];if(label)button.querySelector('span').textContent=label+(form&&index<3&&remaining>0?' '+remaining.toFixed(1)+'s':'');if(hint)button.title=(index===3?'大絕 · ':'')+label+'｜'+hint;});
