    const emblemWallet=globalThis.document?.getElementById('td-shop-emblems');if(emblemWallet)emblemWallet.textContent='✦ '+(this.economy.emblems||0)+' 首領勳章';(this.ui.shopItems||[]).filter(button=>button.dataset.shopItem==='evolution-stone').forEach(button=>{const item=this.shop.offer('evolution-stone'),canBuy=evolution.canBuyStone(this.hero,this.economy,evolution.clearedWave(this));button.querySelector('b').textContent='✦ '+item.name;button.querySelector('small').textContent=item.description;button.querySelector('span').textContent=item.level>=item.max?'已持有／完成':item.emblems+' 枚首領勳章';button.disabled=!canBuy;button.hidden=!item.stage&&!item.level;});
